//! Exact-equality tests of `swadesh_core::nprng` against numpy and CPython
//! outputs stored in `tests/fixtures/` (generated by `tests/gen_rng_fixtures.py`).

use swadesh_core::nprng::{
    default_rng, mean_f64, pairwise_sum_f32, statistics_mean, sort_f64, sum_rows_f32, Pcg64,
    SeedSequence,
};

/// Order-sensitive hash matching `stream_hash` in gen_rng_fixtures.py.
fn stream_hash(vals: &[i64]) -> String {
    const GOLD: u64 = 0x9E37_79B9_7F4A_7C15;
    let mut h: u64 = 0;
    for (i, &v) in vals.iter().enumerate() {
        let mut x = (v as u64).wrapping_add(((i as u64) + 1).wrapping_mul(GOLD));
        x ^= x >> 30;
        x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
        x ^= x >> 27;
        x = x.wrapping_mul(0x94D0_49BB_1331_11EB);
        x ^= x >> 31;
        h = h.wrapping_add(x);
    }
    format!("{h:016x}")
}

fn hex64(s: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(s, 16).unwrap())
}

fn hex32(s: &str) -> f32 {
    f32::from_bits(u32::from_str_radix(s, 16).unwrap())
}

/// `np.random.default_rng(seed).bit_generator.random_raw(1000)`
#[test]
fn pcg64_random_raw_matches_numpy() {
    for line in include_str!("fixtures/pcg64_raw.txt").lines() {
        let mut it = line.split_whitespace();
        let seed: u128 = it.next().unwrap().parse().unwrap();
        let mut bg = Pcg64::new(seed);
        for (i, tok) in it.enumerate() {
            let want: u64 = tok.parse().unwrap();
            assert_eq!(bg.next_u64(), want, "seed {seed} draw {i}");
        }
    }
}

/// Raw next_uint32 (the buffered low/high halves) via integers(0, 2**32).
#[test]
fn next_u32_matches_numpy_raw_range() {
    for line in include_str!("fixtures/u32_raw.txt").lines() {
        let mut it = line.split_whitespace();
        let seed: u128 = it.next().unwrap().parse().unwrap();
        let mut g = default_rng(seed);
        let got = g.integers(0, 1i64 << 32, 1000);
        for (i, tok) in it.enumerate() {
            let want: i64 = tok.parse().unwrap();
            assert_eq!(got[i], want, "seed {seed} draw {i}");
        }
    }
}

#[test]
fn seed_sequence_state_matches_numpy_pcg_words() {
    // Structural check only: generate_state(n, uint64) packs consecutive u32 words
    // low-first. The seeding itself is verified end to end by the PCG64 raw-stream test.
    let ss = SeedSequence::new(12345);
    let w32 = ss.generate_state_u32(8);
    let w64 = ss.generate_state_u64(4);
    for i in 0..4 {
        assert_eq!(w64[i], (w32[2 * i] as u64) | ((w32[2 * i + 1] as u64) << 32));
    }
}

#[test]
fn integers_and_choice_match_numpy() {
    for line in include_str!("fixtures/integers.txt").lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(t[0], "int");
        let (low, high): (i64, i64) = (t[1].parse().unwrap(), t[2].parse().unwrap());
        let (n, seed): (usize, u128) = (t[3].parse().unwrap(), t[4].parse().unwrap());
        let got = default_rng(seed).integers(low, high, n);
        match t[5] {
            "full" => {
                for (i, tok) in t[6..].iter().enumerate() {
                    assert_eq!(got[i], tok.parse::<i64>().unwrap(), "integers {low}..{high} seed {seed} i={i}");
                }
            }
            "hash" => assert_eq!(stream_hash(&got), t[6], "integers {low}..{high} seed {seed} hash"),
            other => panic!("bad mode {other}"),
        }
    }
    for line in include_str!("fixtures/choice.txt").lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(t[0], "choice");
        let n: usize = t[1].parse().unwrap();
        let (rows, cols): (usize, usize) = (t[2].parse().unwrap(), t[3].parse().unwrap());
        let seed: u128 = t[4].parse().unwrap();
        let got: Vec<i64> = default_rng(seed).choice(n, rows, cols).into_iter().map(|v| v as i64).collect();
        match t[5] {
            "full" => {
                assert_eq!(got.len(), t.len() - 6);
                for (i, tok) in t[6..].iter().enumerate() {
                    assert_eq!(got[i], tok.parse::<i64>().unwrap(), "choice n={n} seed={seed} i={i}");
                }
            }
            "hash" => assert_eq!(stream_hash(&got), t[6], "choice n={n} seed={seed} hash"),
            other => panic!("bad mode {other}"),
        }
    }
}

#[test]
fn bool_integers_match_numpy() {
    for line in include_str!("fixtures/bool.txt").lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(t[0], "bool");
        let (rows, cols): (usize, usize) = (t[1].parse().unwrap(), t[2].parse().unwrap());
        let seed: u128 = t[3].parse().unwrap();
        let got = default_rng(seed).integers_bool(rows, cols);
        match t[4] {
            "full" => {
                assert_eq!(got.len(), t.len() - 5);
                for (i, tok) in t[5..].iter().enumerate() {
                    assert_eq!(got[i] as u8, tok.parse::<u8>().unwrap(), "bool seed={seed} i={i}");
                }
            }
            "hash" => {
                let v: Vec<i64> = got.iter().map(|&b| b as i64).collect();
                assert_eq!(stream_hash(&v), t[5], "bool hash seed={seed}");
            }
            other => panic!("bad mode {other}"),
        }
    }
}

#[test]
fn mean_matches_numpy_pairwise() {
    let mut checked = 0;
    for line in include_str!("fixtures/mean.txt").lines() {
        let mut it = line.split_whitespace();
        let want = hex64(it.next().unwrap());
        let xs: Vec<f64> = it.map(hex64).collect();
        let got = mean_f64(&xs);
        assert_eq!(got.to_bits(), want.to_bits(), "mean n={} got={got:e} want={want:e}", xs.len());
        checked += 1;
    }
    assert!(checked >= 150);
}

#[test]
fn f32_pairwise_matches_numpy() {
    for line in include_str!("fixtures/pairwise_f32.txt").lines() {
        let mut it = line.split_whitespace();
        let want = hex32(it.next().unwrap());
        let xs: Vec<f32> = it.map(hex32).collect();
        let got = pairwise_sum_f32(&xs);
        assert_eq!(got.to_bits(), want.to_bits(), "f32 pairwise n={}", xs.len());
    }
}

#[test]
fn statistics_mean_matches_cpython() {
    for line in include_str!("fixtures/statistics_mean.txt").lines() {
        let mut it = line.split_whitespace();
        let want = hex64(it.next().unwrap());
        let xs: Vec<f64> = it.map(hex64).collect();
        let got = statistics_mean(&xs).unwrap();
        if want.is_nan() {
            assert!(got.is_nan(), "statistics.mean({xs:?}) should be NaN, got {got:?}");
        } else {
            assert_eq!(got.to_bits(), want.to_bits(), "statistics.mean n={} got={got:e} want={want:e}", xs.len());
        }
    }
    assert_eq!(statistics_mean(&[]), None);
}

#[test]
fn sort_is_nan_last_and_ascending() {
    let mut xs = vec![3.0, f64::NAN, -1.0, 2.5, f64::INFINITY, -f64::INFINITY, 0.0, f64::NAN];
    sort_f64(&mut xs);
    assert_eq!(&xs[..6], &[-f64::INFINITY, -1.0, 0.0, 2.5, 3.0, f64::INFINITY]);
    assert!(xs[6].is_nan() && xs[7].is_nan());
}

#[test]
fn f32_row_sums_match_numpy() {
    let mut mat: Vec<f32> = Vec::new();
    let (mut rows, mut width) = (0usize, 0usize);
    for line in include_str!("fixtures/f32_rows.txt").lines() {
        let t: Vec<&str> = line.split_whitespace().collect();
        match t[0] {
            "mat" => {
                rows = t[1].parse().unwrap();
                width = t[2].parse().unwrap();
                // Integer counts are converted with `as f32`, which rounds to nearest-even like numpy.
                mat = t[3..].iter().map(|s| s.parse::<i64>().unwrap() as f32).collect();
                assert_eq!(mat.len(), rows * width);
            }
            "sums" => {
                let seed: u128 = t[1].parse().unwrap();
                let n_samples: usize = t[2].parse().unwrap();
                let want: Vec<f32> = t[3..].iter().map(|s| hex32(s)).collect();
                assert_eq!(want.len(), n_samples * width);
                let idxs = default_rng(seed).choice(rows, n_samples, rows);
                for s in 0..n_samples {
                    let sel = &idxs[s * rows..(s + 1) * rows];
                    let got = sum_rows_f32(&mat, width, sel);
                    for j in 0..width {
                        assert_eq!(
                            got[j].to_bits(),
                            want[s * width + j].to_bits(),
                            "rows={rows} width={width} seed={seed} sample={s} col={j}"
                        );
                    }
                }
            }
            other => panic!("bad record {other}"),
        }
    }
}

#[test]
fn seed_12345_first_value_is_known() {
    // Pinned first draw so a broken seeding path fails with a clear message.
    let mut bg = Pcg64::new(12345);
    assert_eq!(bg.next_u64(), 4_193_609_425_186_963_869);
}
